import { execFile } from "node:child_process";
import { readFile, stat, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { promisify } from "node:util";
import type { HappyStats, StatsDay } from "../shared/types.js";

const run = promisify(execFile);

/** Changes that aren't written code: lockfiles, builds, vendored or generated files, snapshots, images. */
const NOISE = /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|poetry\.lock|Cargo\.lock|uv\.lock)$|\.(lock|min\.js|min\.css|map|snap|svg|png|jpe?g|gif|pdf|ipynb|json|jsonl|csv|tsv|psv|txt|xlsx)$|(^|\/)(dist|build|node_modules|vendor|\.next|coverage)\//;

/** Not hand-written code: autogenerated migrations, native shells, static assets, data dumps, vendored code. */
const NOT_CODE = /(^|\/)(alembic\/versions|android|ios|public|data|vendor|third_party|__snapshots__|fixtures)\//;
const LANG: Record<string, string> = {
  py: "Python", ts: "TypeScript", tsx: "TypeScript", js: "JavaScript", jsx: "JavaScript", mjs: "JavaScript", cjs: "JavaScript",
  css: "CSS", scss: "CSS", html: "HTML", sql: "SQL", sh: "Shell", bash: "Shell", zsh: "Shell", md: "Markdown", mdx: "Markdown",
  yaml: "YAML", yml: "YAML", toml: "TOML", go: "Go", rs: "Rust", swift: "Swift", kt: "Kotlin", java: "Java", rb: "Ruby", ipynb: "",
};
const area = (f: string) =>
  f.startsWith("backend/app/") ? "Backend app" : f.startsWith("backend/tests/") || f.includes("/e2e/") || /(^|\/)tests?\//.test(f) ? "Tests" : f.startsWith("frontend/src/") ? "Frontend" : /(^|\/)scripts\//.test(f) ? "Scripts" : f.startsWith("docs/") || f.endsWith(".md") ? "Docs" : "Other";

/** Non-blank lines per language and area across tracked files (skips libraries, generated files and data). */
export async function countLoc(repo: string): Promise<HappyStats["loc"]> {
  const files = (await run("git", ["ls-files", "-z"], { cwd: repo, maxBuffer: 64 * 1024 * 1024 })).stdout.split("\0").filter(Boolean);
  const langs = new Map<string, { lines: number; files: number }>();
  const areas = new Map<string, number>();
  let total = 0;
  const todo = files.filter((f) => !NOISE.test(f) && !NOT_CODE.test(f) && LANG[f.split(".").pop()!.toLowerCase()]);
  for (let i = 0; i < todo.length; i += 64)
    await Promise.all(
      todo.slice(i, i + 64).map(async (f) => {
        try {
          const p = join(repo, f);
          if ((await stat(p)).size > 1024 * 1024) return; // a 1MB+ source file is generated
          const text = await readFile(p, "utf8");
          let n = 0;
          for (const l of text.split("\n")) if (l.trim()) n++;
          const lang = LANG[f.split(".").pop()!.toLowerCase()];
          const e = langs.get(lang) ?? { lines: 0, files: 0 };
          e.lines += n;
          e.files++;
          langs.set(lang, e);
          areas.set(area(f), (areas.get(area(f)) ?? 0) + n);
          if (lang !== "Markdown") total += n; // docs are listed, not counted as code
        } catch {}
      }),
    );
  return {
    total,
    byLang: [...langs.entries()].map(([lang, v]) => ({ lang, ...v })).sort((a, b) => b.lines - a.lines),
    byArea: [...areas.entries()].map(([a, lines]) => ({ area: a, lines })).sort((a, b) => b.lines - a.lines),
  };
}

const day = (t: number) => new Date(t).toLocaleDateString("en-CA");

/**
 * Your last 13 weeks: commits and lines changed (yours, every branch of the main repo, no merges or generated
 * files), plus Happy's own messages and tokens per day.
 */
export type StatsRange = "3m" | "6m" | "1y" | "all";
const RANGE_DAYS: Record<Exclude<StatsRange, "all">, number> = { "3m": 91, "6m": 182, "1y": 365 };

export async function computeStats(repo: string, messagesByDay: Map<string, number>, usageByDay: Record<string, { tokens: number; costUsd: number }>, range: StatsRange = "3m", cacheFile?: string): Promise<HappyStats> {
  // "all" = back to your first commit in this repo.
  let DAYS = range === "all" ? 0 : RANGE_DAYS[range];
  if (!DAYS) {
    try {
      const email0 = (await run("git", ["config", "user.email"], { cwd: repo })).stdout.trim();
      const first = (await run("git", ["log", "--all", "--reverse", `--author=${email0}`, "--format=%ct"], { cwd: repo, maxBuffer: 64 * 1024 * 1024 })).stdout.split("\n")[0];
      DAYS = Math.max(91, Math.ceil((Date.now() - Number(first) * 1000) / 86400_000) + 1);
    } catch {
      DAYS = 365;
    }
  }
  const days = new Map<string, StatsDay>();
  const now = Date.now();
  for (let i = DAYS - 1; i >= 0; i--) {
    const d = day(now - i * 86400_000);
    days.set(d, { date: d, commits: 0, added: 0, deleted: 0, messages: messagesByDay.get(d) ?? 0, tokens: usageByDay[d]?.tokens ?? 0, costUsd: usageByDay[d]?.costUsd ?? 0 });
  }
  let email = "";
  let error: string | undefined;
  try {
    email = (await run("git", ["config", "user.email"], { cwd: repo })).stdout.trim();
    // Commit list is cheap; line counts are the slow part, so they're remembered per commit on disk.
    const list0 = (
      await run("git", ["log", "--all", "--no-merges", `--author=${email}`, `--since=${DAYS + 1} days ago`, "--format=%H %ct"], { cwd: repo, maxBuffer: 64 * 1024 * 1024 })
    ).stdout
      .split("\n")
      .filter(Boolean)
      .map((l) => l.split(" ") as [string, string]);
    const cache: Record<string, [number, number]> = cacheFile ? await readFile(cacheFile, "utf8").then(JSON.parse).catch(() => ({})) : {};
    const missing = list0.map(([h]) => h).filter((h) => !cache[h]);
    for (let i = 0; i < missing.length; i += 2000) {
      const chunk = missing.slice(i, i + 2000);
      const child = execFile("git", ["log", "--no-walk", "--stdin", "--pretty=format:@%H", "--numstat"], { cwd: repo, maxBuffer: 256 * 1024 * 1024 });
      const out = new Promise<string>((res, rej) => {
        let buf = "";
        child.stdout!.on("data", (d) => (buf += d));
        child.on("close", () => res(buf));
        child.on("error", rej);
      });
      child.stdin!.end(chunk.join("\n") + "\n");
      let cur: [number, number] | undefined;
      for (const line of (await out).split("\n")) {
        if (line.startsWith("@")) cache[line.slice(1)] = cur = [0, 0];
        else if (cur && line) {
          const [a, d, file] = line.split("\t");
          if (a === "-" || !file || NOISE.test(file)) continue;
          cur[0] += Number(a) || 0;
          cur[1] += Number(d) || 0;
        }
      }
    }
    if (missing.length && cacheFile) await writeFile(cacheFile, JSON.stringify(cache)).catch(() => {});
    const seen = new Set<string>();
    for (const [h, ct] of list0) {
      if (seen.has(h)) continue;
      seen.add(h);
      const d = days.get(day(Number(ct) * 1000));
      if (!d) continue;
      d.commits++;
      d.added += cache[h]?.[0] ?? 0;
      d.deleted += cache[h]?.[1] ?? 0;
    }
  } catch (e) {
    error = `Couldn't read git history in ${repo}: ${String((e as Error).message).split("\n")[0]}`;
  }
  const list = [...days.values()];
  // Streaks: consecutive days with at least one commit (today may still be empty without breaking it).
  let current = 0;
  for (let i = list.length - 1; i >= 0; i--) {
    if (list[i].commits) current++;
    else if (i !== list.length - 1) break;
  }
  let longest = 0;
  let run_ = 0;
  for (const d of list) {
    run_ = d.commits ? run_ + 1 : 0;
    longest = Math.max(longest, run_);
  }
  const loc = await countLoc(repo).catch(() => undefined);
  return { generatedAt: now, repo, email, range, days: list, streak: { current, longest }, loc, error };
}
